use pervasive::vec::Vec;
use verus::prelude::*;

verus! {

    /// Returns the index of the first occurrence of the maximum element in a non-empty Vec<i8>.
    pub fn nanargmax(a: Vec<i8>) -> usize
        requires
            a.len() > 0,
        ensures
            // The returned index is within bounds
            result < a.len(),
        ensures
            // The value at result is ≥ every element in a
            forall(|j: usize| j < a.len() ==> a[result] >= a[j]),
        ensures
            // If there is a tie for the maximum, result is the first occurrence
            forall(|j: usize| j < result ==> a[j] < a[result])
    {
        let n = a.len();
        // We know n > 0 by the requires clause
        assert(n > 0);

        // max_i will track the index of the maximum seen so far
        let mut max_i: usize = 0;
        // i will scan the array from 1 up to n-1
        let mut i: usize = 1;

        // Loop invariant captures:
        //   1) 1 ≤ i ≤ n
        //   2) max_i < i
        //   3) For all j < i, a[max_i] ≥ a[j]
        // We use decreases on (n - i) to ensure termination.
        while i < n
            invariant
                1 <= i && i <= n,
            invariant
                max_i < i,
            invariant
                forall(|j: usize| j < i ==> a[max_i] >= a[j]),
            decreases
                n - i
        {
            if a[i] > a[max_i] {
                max_i = i;
            }
            i = i + 1;
        }

        // After the loop, i == n, so max_i < n and
        // ∀ j < n, a[max_i] ≥ a[j], which matches our postconditions.
        max_i
    }
}